# H2 콘솔에서
select id, user_name, session_start, statement
from information_schema.sessions;

# ID | USER_NAME | SESSION_START       | STATEMENT
# 3  | SA        | 2026-09-09 07:48:01 | select id, user_name, ...
# 4  | SA        | 2026-09-09 07:48:05 | null
# 5  | SA        | 2026-09-09 07:48:05 | null
# 6  | SA        | 2026-09-09 07:48:05 | null

# 3 번이 콘솔 자기 자신, 4~6 번이 애플리케이션

# 세션 4 에서 트랜잭션을 열면
con1.setAutoCommit(false);
con1.prepareStatement("update member set money=5000 where member_id='memberA'")
   .executeUpdate();

# 콘솔에서 조회
select * from member where member_id = 'memberA';
# MONEY = 10000    <- 세션 3 에서는 안 보인다

